package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0          // PIC 9(4) len=4 = 0
var WsR4 int64 = 0         // PIC 9(3) len=3 = 0
var WsR100 int64 = 0       // PIC 9(3) len=3 = 0
var WsR400 int64 = 0       // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0     // PIC 99 len=2 = 0
var WsValid int64 = 0      // PIC 99 len=2 = 0
var WsBadMonth int64 = 0   // PIC 99 len=2 = 0
var WsBadDay int64 = 0     // PIC 99 len=2 = 0

var dateRec DateRec
var dateFile *os.File
var dateScanner *bufio.Scanner

// use decimal to keep import
var _ = decimal.NewFromInt(0)

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncStore(v int64, digits int) int64 {
	if digits <= 0 {
		return v
	}
	p := pow10(digits)
	if p == 0 {
		return v
	}
	if v >= 0 {
		return v % p
	}
	// for negative keep sign and low order digits
	return -((-v) % p)
}

func format9(v int64, digits int) string {
	p := pow10(digits)
	var tv int64
	if v >= 0 {
		tv = v % p
	} else {
		tv = -((-v) % p)
		// negative not expected for this program; but format as positive with sign?
		// For PIC 9 unsigned we will not have negative.
		if tv < 0 {
			tv = -tv
		}
	}
	// ensure positive for formatting width
	if tv < 0 {
		tv = -tv
	}
	return fmt.Sprintf("%0*d", digits, tv)
}

func parseNum(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	// remove internal spaces if any
	trimmed = strings.ReplaceAll(trimmed, " ", "")
	if trimmed == "" {
		return 0
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func MAIN_PARA() {
	// OPEN INPUT DATE-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// treat as empty file
		dateScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		dateFile = f
		dateScanner = bufio.NewScanner(f)
	}
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", format9(WsValid, 2), format9(WsBadMonth, 2), format9(WsBadDay, 2))
}

func READ_PARA() {
	if dateScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if dateScanner.Scan() {
		line := dateScanner.Text()
		// Scanner removes trailing \r for CRLF, otherwise keeps content
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = truncStore(parseNum(line[4:8]), 4)
		dateRec.DtMm = truncStore(parseNum(line[8:10]), 2)
		dateRec.DtDd = truncStore(parseNum(line[10:12]), 2)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = truncStore(WsBadMonth+1, 2)
		fmt.Printf("%s BAD MONTH %s\n", dateRec.DtId, format9(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = truncStore(WsBadDay+1, 2)
			fmt.Printf("%s BAD DAY %s MAX %s\n", dateRec.DtId, format9(dateRec.DtDd, 2), format9(WsMaxDay, 2))
		} else {
			WsValid = truncStore(WsValid+1, 2)
			fmt.Printf("%s VALID %s-%s-%s\n", dateRec.DtId, format9(dateRec.DtYyyy, 4), format9(dateRec.DtMm, 2), format9(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = truncStore(dateRec.DtYyyy/4, 4)
	WsR4 = truncStore(dateRec.DtYyyy%4, 3)
	// DIVIDE DT-YYYY BY 100 GIVING WS-Q REMAINDER WS-R100
	WsQ = truncStore(dateRec.DtYyyy/100, 4)
	WsR100 = truncStore(dateRec.DtYyyy%100, 3)
	// DIVIDE DT-YYYY BY 400 GIVING WS-Q REMAINDER WS-R400
	WsQ = truncStore(dateRec.DtYyyy/400, 4)
	WsR400 = truncStore(dateRec.DtYyyy%400, 3)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = truncStore(29, 2)
		} else {
			WsMaxDay = truncStore(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncStore(30, 2)
	default:
		WsMaxDay = truncStore(31, 2)
	}
}

func main() {
	MAIN_PARA()
}
